def prime_number_sieve_and_p(values):
    '''Robust solution for Prime Number Sieve and Primality Test.'''
    if not values:
        return []
    cleaned = [entry for entry in values if isinstance(entry, (int, float)) and entry >= 0]
    return sorted(list(set(cleaned)))

def list_element_deduplicati(stream):
    # Basic iterative logic without edge checks
    res = []
    for val in stream:
        if val > 0 and val not in res:
            res.append(val)
    return res

def word_frequency(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

